//! When the `rt` feature is enabled, place the active chip's `device.x` linker
//! fragment (generated by `scripts/pac/gen_interrupts.py`) where cortex-m-rt's
//! `link.x` can `INCLUDE` it.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    if env::var_os("CARGO_FEATURE_RT").is_none() {
        return;
    }

    // Chip features are mutually exclusive; pick the first that is enabled.
    let device_x = if env::var_os("CARGO_FEATURE_IMX95").is_some() {
        include_str!("src/interrupts/imx95.x")
    } else if env::var_os("CARGO_FEATURE_IMX93").is_some() {
        include_str!("src/interrupts/imx93.x")
    } else {
        return;
    };

    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    fs::write(out.join("device.x"), device_x).unwrap();
    println!("cargo:rustc-link-search={}", out.display());
    println!("cargo:rerun-if-changed=src/interrupts/imx95.x");
    println!("cargo:rerun-if-changed=src/interrupts/imx93.x");
}
